import React from 'react';
import { Product } from './ProductCard';

interface CartItem {
  product: Product;
  qty: number;
}

interface CartDrawerProps {
  isOpen: boolean;
  onClose: () => void;
  items: CartItem[];
  onRemove: (id: string) => void;
  onCheckout: () => void;
}

export const CartDrawer: React.FC<CartDrawerProps> = ({
  isOpen,
  onClose,
  items,
  onRemove,
  onCheckout,
}) => {
  const total = items.reduce((sum, item) => sum + item.product.price * item.qty, 0);

  return (
    <>
      {isOpen && <div className="drawer-backdrop" onClick={onClose} />}
      <div className={`cart-drawer ${isOpen ? 'open' : ''}`}>
        <div className="drawer-header">
          <h3>Active Order Items</h3>
          <button
            onClick={onClose}
            style={{ background: 'none', border: 'none', color: '#94a3b8', fontSize: '1.25rem', cursor: 'pointer' }}
          >
            ✕
          </button>
        </div>
        <div className="drawer-items">
          {items.length === 0 ? (
            <p style={{ color: '#94a3b8', textAlign: 'center', marginTop: '3rem' }}>
              Your cart is currently empty.
            </p>
          ) : (
            items.map((item) => (
              <div key={item.product.id} className="drawer-item">
                <div>
                  <div style={{ fontWeight: 700, fontSize: '0.95rem' }}>{item.product.title}</div>
                  <div style={{ color: '#94a3b8', fontSize: '0.85rem' }}>
                    ${item.product.price} × {item.qty}
                  </div>
                </div>
                <button
                  onClick={() => onRemove(item.product.id)}
                  style={{
                    background: 'none',
                    border: 'none',
                    color: '#f87171',
                    fontSize: '0.85rem',
                    cursor: 'pointer',
                    fontWeight: 600,
                  }}
                >
                  Remove
                </button>
              </div>
            ))
          )}
        </div>
        <div className="drawer-footer">
          <div className="total-row">
            <span>Subtotal</span>
            <span style={{ color: '#38bdf8' }}>${total}</span>
          </div>
          <button
            className="btn-primary"
            style={{ width: '100%' }}
            onClick={onCheckout}
            disabled={items.length === 0}
          >
            Complete Order
          </button>
        </div>
      </div>
    </>
  );
};
